style.css:
@-moz-document domain("google.com"), domain("google.ca") {
/* Google Homepage */
    html, body {
        background: url("https://i.imgur.com/waY5yv2.jpg") no-repeat center center fixed !important;
        background-size: cover !important; /* Ensures the image covers the entire screen without black borders */
        background-color: black !important; /* Fallback color */
    }

    /* Transparent elements on the homepage */
    #main, #searchform, .L3eUgb {
        background: transparent !important;
    }

    /* Google Search Results Page */
    html:not([class*="hp"]) body {
        background-color: black !important; /* Solid black background for search results */
        background-image: none !important; /* Remove the wallpaper */
    }
}
